    [['사업비','cost','--peach-text'],['수입','rev','--green']].forEach(function(row){h+='<tr><td class="cat" style="padding-left:8px;color:var('+row[2]+')">'+row[0]+'</td>'+years.map(function(y){var r=rows[allY.indexOf(y)];return '<td style="text-align:right;color:var(--neutral-text);'+yearStyle(r.year)+'">'+_eokCell(cell(r,row[1]))+'</td>';}).join('')+'<td class="tot" style="padding-right:8px;text-align:right;color:var('+row[2]+')">'+_eokCell(_finEok(total(row[1])))+'</td></tr>';});
