function _prGrpFinance(f,status){
 if(!f)return null;
 var budget=(f.bud!==null&&f.bud!==undefined&&String(f.bud).trim()!==''&&isFinite(Number(f.bud)))?Number(f.bud):null;
 var planned=status!=='완료'&&budget!==null;
 return {cost:planned?budget:_finCalc(f).cost,rev:Number(f.rev)||0,basis:planned?'전체 예산':'전체 집행액·수수료'};
}

_finRows:
function _finRows(year){
  var out=[],seen={};
  (_finState.rows||[]).forEach(function(r){
    var o=_finFromSheet(r);
    if(!o.no||seen[o.no])return;
    if(year&&o.y&&o.y!==year)return;
    seen[o.no]=1; out.push(o);
  });
  if(!out.length)_finSeed(year).forEach(function(s){ if(!seen[s.no])out.push(_finFromSeed(s,year)); });   /* [260902] 시트가 그 연도를 한 줄이라도 가지면 씨앗 무발화 — 사업NO 체계 통일(YY-aNN) 뒤 구형 씨앗 NO가 중복으로 되살아나는 것 차단 */
  out.sort(function(a,b){ return a.no<b.no?-1:(a.no>b.no?1:0); });
  return out;
}
